import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../app_helpers.dart';
import '../database/db_helper.dart';
class Reports extends StatefulWidget{const Reports({super.key});@override State<Reports> createState()=>_ReportsState();}
class _ReportsState extends State<Reports>{bool monthly=true;@override Widget build(BuildContext c)=>FutureBuilder(future:DB.i.tx(),builder:(c,s){final rows=s.data??[];final now=DateTime.now();final chosen=rows.where((e){final d=DateTime.tryParse(e['tanggal'])??now;return d.year==now.year&&d.month==now.month&&(monthly||d.day==now.day);}).toList();double a=0,b=0;for(final e in chosen){final n=(e['jumlah'] as num).toDouble();if(e['jenis']=='Pemasukan')a+=n;else b+=n;}return ListView(children:[heading('Laporan','Ringkasan kas yang mudah dipahami'),Padding(padding:const EdgeInsets.symmetric(horizontal:18),child:SegmentedButton<bool>(segments:const [ButtonSegment(value:false,label:Text('Harian')),ButtonSegment(value:true,label:Text('Bulanan'))],selected:{monthly},onSelectionChanged:(v)=>setState(()=>monthly=v.contains(true)))),Padding(padding:const EdgeInsets.all(18),child:card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(monthly?'LAPORAN BULANAN':'LAPORAN HARIAN'),Text(money.format(a-b),style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold,color:navy)),const Text('Saldo periode terpilih')]))),Padding(padding:const EdgeInsets.symmetric(horizontal:18),child:card(Column(children:[_line('Total pemasukan',a,green),_line('Total pengeluaran',b,red),const Divider(),_line('Saldo akhir',a-b,navy)])))]);});Widget _line(String t,double v,Color c)=>Padding(padding:const EdgeInsets.symmetric(vertical:9),child:Row(children:[Expanded(child:Text(t)),Text(money.format(v),style:TextStyle(color:c,fontWeight:FontWeight.bold))]));}
